/**
 * Files in S3-compatible object storage (rule 28, task 2-8). Two spaces:
 *
 * - `private`: everything uploaded, and everything not yet published; read only through a
 *   short-lived signed link;
 * - `public`: what is published, served at S3_PUBLIC_BASE_URL (later behind a domestic
 *   CDN; task 2-8 decision 3).
 *
 * Keys are generated by the application (ids, never a file name a user typed).
 */
export type StorageSpace = 'private' | 'public';

export interface ObjectStorage {
  /** Whether S3 is configured; when not, every operation refuses (storage_unavailable). */
  readonly configured: boolean;
  put(space: StorageSpace, key: string, body: Buffer, contentType: string): Promise<void>;
  get(space: StorageSpace, key: string): Promise<Buffer>;
  /** Copies an object between spaces (publishing). */
  copy(from: StorageSpace, key: string, to: StorageSpace, toKey?: string): Promise<void>;
  /**
   * Removes an object: only for the public copy of a file no published version shows any
   * more. The private original and its variants are kept (rule 7).
   */
  remove(space: StorageSpace, key: string): Promise<void>;
  /** A GET link to a private object, valid for `seconds`. */
  /**
   * A short-lived signed link to a private file (rule 28). Served as a download
   * (`Content-Disposition: attachment`, never cached, task 9-3 R12) unless `inline`: a preview
   * the page shows itself (a profile's draft photo).
   */
  signedUrl(key: string, seconds: number, options?: { inline?: boolean }): Promise<string>;
  /** Where a public object is served. */
  publicUrl(key: string): string;
}

export const OBJECT_STORAGE = Symbol('OBJECT_STORAGE');
